import {
  MeshStandardNodeMaterial,
  color,
  uv,
  mix,
  smoothstep,
  vec3,
  uniform,
  nodeFrame
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  // Create local timelines list for cleanup
  const activeTimelines = [];

  // ==========================================
  // 1. BACKDROP & LIGHTING STAGE
  // ==========================================
  // Create a stylized dark steel stage background
  const bgGeo = new THREE.PlaneGeometry(8, 6);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.7,
    metalness: 0.4,
    color: 0x0b0b10
  });
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.6);
  group.add(bgMesh);

  // Rim lights to highlight the button, as specified by DESIGN DOCTRINE (lighting like a product shot)
  const rimLightLeft = new THREE.DirectionalLight('#ff2a38', 1.2);
  rimLightLeft.position.set(-3, 2, 2);
  group.add(rimLightLeft);

  const rimLightRight = new THREE.DirectionalLight('#e8ecf2', 0.8);
  rimLightRight.position.set(3, -2, 2);
  group.add(rimLightRight);

  // Local key light
  const keyLight = new THREE.DirectionalLight('#ffffff', 1.1);
  keyLight.position.set(0, 4, 3);
  group.add(keyLight);

  // ==========================================
  // 2. CONTACT SHADOW
  // ==========================================
  const shadowGeo = new THREE.PlaneGeometry(3.0, 1.0);
  const shadowMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    roughness: 1.0,
    metalness: 0.0
  });
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.1, -0.15);
  group.add(shadowMesh);

  // ==========================================
  // 3. CTA BUTTON (3D Plane with TSL Material)
  // ==========================================
  const buttonWidth = 2.6;
  const buttonHeight = 0.68;

  // We approximate the chamfer/emissive-edge & engineered gradient in custom high-fidelity TSL Nodes
  const faceGeo = new THREE.BoxGeometry(buttonWidth, buttonHeight, 0.06);

  // TSL Uniforms for interactivity
  const hoverState = uniform(0.0); // 0.0 to 1.0
  const pressState = uniform(0.0); // 0.0 to 1.0

  const btnMaterial = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22
  });

  // Engineered gradient TSL implementation
  // Gradient stops: #ff4450 (0.0) -> #ff2a38 (0.55) -> #c1121f (1.0)
  // Inside the uv y: face vertical coordinates range from 0 to 1
  const uvNode = uv();
  const vPos = uvNode.y;

  const color0 = color('#ff4450');
  const color1 = color('#ff2a38');
  const color2 = color('#c1121f');

  // Hard seam line at 50% height (y = 0.5) with 0.01 tolerance
  const isBelowSeam = smoothstep(0.495, 0.505, vPos);
  const topGradient = mix(color0, color1, vPos.mul(2.0));
  const bottomGradient = mix(color1, color2, vPos.sub(0.5).mul(2.0));
  const baseGradColor = mix(topGradient, bottomGradient, isBelowSeam);

  // Perimeter emissive border edge: 0.015 thin frame
  const edgeDistX = vPos.sub(0.5).abs().mul(2.0); // normalized distance from vertical center
  const edgeDistY = uvNode.x.sub(0.5).abs().mul(2.0); // normalized distance from horiz center
  const edgeThreshold = 0.95;
  const isEdge = smoothstep(edgeThreshold, 1.0, edgeDistX).or(smoothstep(edgeThreshold, 1.0, edgeDistY));

  // Dynamic emissive intensity scaling from 1.6 to 2.2 on hover
  const glowIntensity = mix(1.6, 2.2, hoverState);
  const rimColor = color('#ff2a38').mul(glowIntensity);

  // Set physical node attributes
  btnMaterial.colorNode = baseGradColor;
  btnMaterial.emissiveNode = mix(vec3(0.0), rimColor, isEdge);

  const buttonMesh = new THREE.Mesh(faceGeo, btnMaterial);
  buttonMesh.position.set(0, 0, 0.03); // Slightly out
  group.add(buttonMesh);

  // ==========================================
  // 4. TYPOGRAPHY / TEXT
  // ==========================================
  // Primary CTA Label
  const ctaLabel = ctx.fontAtlas.createText('BEGIN COMMISSION', {
    fontSize: 0.14,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 3
  });
  // Anchor on top of button face
  ctaLabel.position.set(0, 0, 0.07);
  buttonMesh.add(ctaLabel);

  // Subtitle / Caption below button
  const captionLabel = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', {
    fontSize: 0.07,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 6
  });
  captionLabel.position.set(0, -0.55, 0);
  group.add(captionLabel);

  // ==========================================
  // 5. ANIMATIONS & INTERACTIONS
  // ==========================================

  // Entrance Anim: Weighted Settle (1.04 -> 1.0 over 900ms)
  buttonMesh.scale.set(1.04, 1.04, 1.04);
  const entranceTl = gsap.to(buttonMesh.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  });
  activeTimelines.push(entranceTl);

  // Hover Interactions
  const onPointerOver = () => {
    gsap.to(buttonMesh.position, {
      z: 0.09,
      duration: 0.18,
      ease: 'power2.out'
    });
    // Trigger TSL transition for Glow intensity
    gsap.to(hoverState, {
      value: 1.0,
      duration: 0.18,
      ease: 'power2.out',
      onUpdate: () => {
        nodeFrame.update();
      }
    });
  };

  const onPointerOut = () => {
    gsap.to(buttonMesh.position, {
      z: 0.03,
      duration: 0.25,
      ease: 'power2.out'
    });
    gsap.to(hoverState, {
      value: 0.0,
      duration: 0.25,
      ease: 'power2.out',
      onUpdate: () => {
        nodeFrame.update();
      }
    });
    gsap.to(buttonMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2,
      ease: 'power1.out'
    });
  };

  const onPointerDown = () => {
    // Press State: scale to 0.97
    gsap.to(buttonMesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.2)'
    });
    // Shrink and deepen shadow plane
    gsap.to(shadowMesh.scale, {
      x: 0.9,
      y: 0.9,
      duration: 0.12,
      ease: 'back.out(1.2)'
    });
    gsap.to(shadowMat, {
      opacity: 0.5,
      duration: 0.12
    });
  };

  const onPointerUp = () => {
    gsap.to(buttonMesh.scale, {
      x: 1.02, // slight bounce settle back to hover state
      y: 1.02,
      z: 1.02,
      duration: 0.2,
      ease: 'power3.out',
      onComplete: () => {
        gsap.to(buttonMesh.scale, {
          x: 1.0,
          y: 1.0,
          z: 1.0,
          duration: 0.2
        });
      }
    });
    gsap.to(shadowMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.2,
      ease: 'power3.out'
    });
    gsap.to(shadowMat, {
      opacity: 0.35,
      duration: 0.2
    });

    // Trigger router navigation (or general emit Action)
    ctx.emit('navigate', { to: 'hub-features' });
  };

  // Wire Interaction Handlers to UserData (Kriptik runtime handles raycasting)
  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp
  };

  // Cleanup handler
  group.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    bgMat.dispose();
    bgGeo.dispose();
    shadowMat.dispose();
    shadowGeo.dispose();
    faceGeo.dispose();
    btnMaterial.dispose();
  };

  return group;
}
